        RAISE EXCEPTION 'Expected the previous tool versions (''open_analysis_session'', ''v4'')';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name = 'open_analysis_session' AND version = 'v5')) THEN
