    END IF;
END
$preflight$;

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
SELECT tool_name, tool_family, tool_type, next.purpose, next.input_schema::jsonb, output_schema,
       execution_type, handler_name, default_output_rows, max_output_rows,
       max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
       timeout_seconds, max_output_bytes, max_llm_result_rows,
       max_llm_result_bytes, max_llm_result_tokens,
       requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
       tool_specific_limits || '{"design":"EXEC.md EXEC-OUTPUT-REUSE","open_analysis_session":"same conversation only; a research session is never taken over","registry_state":"registered from code (market-ai-orc) under the dev flags, inactive here"}'::jsonb, next.version, false
FROM public."Tool_Catalog" AS previous
JOIN (VALUES
    ('open_analysis_session', 'v4', 'v5', '{"additionalProperties":false,"properties":{"close_session_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Optional: a session of this answer to close before opening, only when the open was refused with SESSION_LIMIT_PER_REQUEST; pick one that is completed or no longer needed (its released outputs stay readable, its variables are gone). Null otherwise. Limits: matching ^sess_[0-9a-f]{24}$."},"input_bundle_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"input_bundle_id of a READY bundle; null to compute on this conversation''s released tables (or its warm session) without a data need. Limits: matching ^bundle_[0-9a-f]{24}$."}},"required":["input_bundle_id","close_session_id"],"type":"object"}',
     'Open a persistent Python analysis session on a READY governed bundle (input_bundle_id from prepare_data_bundle). Returns session_id, the datasets (data_request_id, logical name, columns, rows_extracted with the buffer rows, rows_in_ranges inside the approved ranges, ranges, quality flags), the relationships with their join semantics, the helper functions and the limits. Variables and functions persist across run_python calls until the session closes (idle timeout, limits, or a restart of the sandbox: then open a new session on the same bundle). input_bundle_id null: computing on this conversation''s released tables needs no data need; the warm session of an earlier message is taken over (its variables stay), else a session opens on the released tables only (datasets empty; read them with load_output). A data need is for data no released table holds. Each READY bundle gets its own session. One answer may keep up to four sessions open at once, and opening one never closes another; activity in any of them keeps all of them open while the answer runs. An open beyond the limit is refused (SESSION_LIMIT_PER_REQUEST) with this answer''s open sessions listed: continue in one of them, or open again with close_session_id naming a completed or unneeded one of them.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'open_analysis_session' AND version = 'v5'))) <> 1 THEN
